fn median(r: f32, g: f32, b: f32) -> f32 {
    return max(min(r, g), min(max(r, g), b));
}

let pxRange = prop.pxRange;
let sz = vec2f(textureDimensions(font_texture, 0));

// Hardware derivatives for Screen-Space anti-aliasing
let uv = input.texCoord * sz;
let dx = dpdxFine(uv);
let dy = dpdyFine(uv);
let toPixels = pxRange * inverseSqrt(dot(dx, dx) + dot(dy, dy));

let msdf = textureSample(font_texture, font_sampler, input.texCoord);
let sigDist = median(msdf.r, msdf.g, msdf.b) - 0.5;

let edgeWidth = AA / toPixels;
var alpha = smoothstep(-edgeWidth, edgeWidth, sigDist);

